	private sealed class AssetIdentity
	{
		public long Bytes { get; }

		public string Sha256 { get; }

		public AssetIdentity(long bytes, string sha256)
		{
			Bytes = bytes;
			Sha256 = sha256;
		}
	}

	private sealed class AssetSpec
	{
		public string Path { get; }

		public AssetIdentity Desired { get; }

		public string LoadedDictionary { get; }

		public bool AllowAbsent { get; }

		public IReadOnlyList<AssetIdentity> Preimages { get; }

		public string? RequiredSourcePath { get; }

		public AssetIdentity? RequiredSource { get; }

		public AssetSpec(string path, long bytes, string sha256, string loadedDictionary, bool allowAbsent, params AssetIdentity[] preimages)
		{
			Path = path;
			Desired = new AssetIdentity(bytes, sha256);
			LoadedDictionary = loadedDictionary;
			AllowAbsent = allowAbsent;
			Preimages = preimages;
		}

		public AssetSpec(string path, long bytes, string sha256, string loadedDictionary, bool allowAbsent, string requiredSourcePath, AssetIdentity requiredSource)
			: this(path, bytes, sha256, loadedDictionary, allowAbsent)
		{
			RequiredSourcePath = requiredSourcePath;
			RequiredSource = requiredSource;
		}
	}

	private sealed class EmbeddedAsset
	{
		public AssetSpec Spec { get; }

		public byte[] Bytes { get; }

		public EmbeddedAsset(AssetSpec spec, byte[] bytes)
		{
			Spec = spec;
			Bytes = bytes;
		}
	}

	private sealed class GamedataMutation
	{
		public uint Id { get; }

		public EmbeddedAsset Asset { get; }

		public object? Original { get; }

		public byte[]? OriginalBytes { get; }

		public object Replacement { get; }

		public bool Assigned { get; set; }

		public GamedataMutation(uint id, EmbeddedAsset asset, object? original, byte[]? originalBytes, object replacement)
		{
			Id = id;
			Asset = asset;
			Original = original;
			OriginalBytes = originalBytes;
			Replacement = replacement;
		}
	}

