	public static IReadOnlyDictionary<string, byte[]> EmbeddedAssetsForTests()
	{
		return ReadEmbeddedAssets().ToDictionary<EmbeddedAsset, string, byte[]>((EmbeddedAsset asset) => asset.Spec.Path, (EmbeddedAsset asset) => (byte[])asset.Bytes.Clone(), StringComparer.Ordinal);
	}

	public static void ApplyEmbeddedAssetTransactionForTests(IDictionary<string, byte[]> cache, int failAfterAssignments = -1)
	{
		if (cache == null)
		{
			throw new ArgumentNullException("cache");
		}
		IReadOnlyList<EmbeddedAsset> readOnlyList = ReadEmbeddedAssets();
		Dictionary<string, byte[]> dictionary = new Dictionary<string, byte[]>(StringComparer.Ordinal);
		foreach (EmbeddedAsset item in readOnlyList)
		{
			ValidateRequiredSource(item.Spec, cache);
			if (cache.TryGetValue(item.Spec.Path, out byte[] value))
			{
				ValidatePreimage(item.Spec, value);
				dictionary.Add(item.Spec.Path, value);
				continue;
			}
			if (!item.Spec.AllowAbsent)
			{
				throw new InvalidOperationException("Test cache lacks required preimage " + item.Spec.Path);
			}
			dictionary.Add(item.Spec.Path, null);
		}
		List<string> list = new List<string>(readOnlyList.Count);
		try
		{
			foreach (EmbeddedAsset item2 in readOnlyList)
			{
				cache[item2.Spec.Path] = (byte[])item2.Bytes.Clone();
				list.Add(item2.Spec.Path);
				ValidateDesired(item2.Spec, cache[item2.Spec.Path]);
				if (failAfterAssignments >= 0 && list.Count == failAfterAssignments)
				{
					throw new InvalidOperationException("Injected embedded-asset failure.");
				}
			}
		}
		catch
		{
			for (int num = list.Count - 1; num >= 0; num--)
			{
				string key = list[num];
				byte[] array = dictionary[key];
				if (array == null)
				{
					cache.Remove(key);
				}
				else
				{
					cache[key] = array;
				}
			}
			throw;
		}
	}

	private static IReadOnlyList<EmbeddedAsset> ReadEmbeddedAssets()
	{
		ValidateManifest();
		using Stream stream = typeof(EmbeddedAssetRuntime).Assembly.GetManifestResourceStream("ScomFieldFixes.FieldFixAssets.sanpack") ?? throw new MissingManifestResourceException("Missing embedded resource ScomFieldFixes.FieldFixAssets.sanpack");
		using ZipArchive zipArchive = OpenValidatedAssetPack(stream);
		ZipArchiveEntry[] source = zipArchive.Entries.Where((ZipArchiveEntry entry) => !string.IsNullOrEmpty(entry.Name)).ToArray();
		string[] second = Specs.Select((AssetSpec spec) => spec.Path).OrderBy<string, string>((string path) => path, StringComparer.Ordinal).ToArray();
		if (!source.Select((ZipArchiveEntry entry) => entry.FullName).SequenceEqual(second, StringComparer.Ordinal) || source.Any((ZipArchiveEntry entry) => entry.Length != entry.CompressedLength))
		{
			throw new InvalidOperationException("Embedded Field Fix pack allowlist, order, or store mode drifted.");
		}
		Dictionary<string, ZipArchiveEntry> dictionary = source.ToDictionary((ZipArchiveEntry entry) => entry.FullName, StringComparer.Ordinal);
		List<EmbeddedAsset> list = new List<EmbeddedAsset>(Specs.Count);
		foreach (AssetSpec spec in Specs)
		{
			byte[] bytes = ReadExactly(dictionary[spec.Path]);
			ValidateDesired(spec, bytes);
			list.Add(new EmbeddedAsset(spec, bytes));
		}
		return list;
	}

	private static byte[] ReadExactly(ZipArchiveEntry entry)
	{
		byte[] array = new byte[checked((int)entry.Length)];
		using Stream stream = entry.Open();
		int num;
		for (int i = 0; i < array.Length; i += num)
		{
			num = stream.Read(array, i, array.Length - i);
			if (num == 0)
			{
				throw new EndOfStreamException("Embedded asset ended early: " + entry.FullName);
			}
		}
		if (stream.ReadByte() != -1)
		{
			throw new InvalidDataException("Embedded asset exceeded its declared length: " + entry.FullName);
		}
		return array;
	}

	private static ZipArchive OpenValidatedAssetPack(Stream stream)
	{
		if (!stream.CanSeek || stream.Length != 109598131 || !string.Equals(Hash(stream), "e633f38faba2899c03fa837b228171a754fdf164c68f5c48309eeb43544cac21", StringComparison.OrdinalIgnoreCase))
		{
			throw new InvalidOperationException("Embedded Field Fix asset pack identity drifted.");
		}
		stream.Position = 0L;
		return new ZipArchive(stream, ZipArchiveMode.Read, leaveOpen: true);
	}

	private static void ValidateManifest()
	{
		if (Specs.Count != 5249 || Specs.Select((AssetSpec spec) => spec.Path).Distinct<string>(StringComparer.Ordinal).Count() != 5249 || Specs.Any((AssetSpec spec) => !IsSha256(spec.Desired.Sha256) || spec.Desired.Bytes <= 0 || spec.Preimages.Any((AssetIdentity preimage) => preimage.Bytes <= 0 || !IsSha256(preimage.Sha256)) || spec.RequiredSourcePath == null != (spec.RequiredSource == null) || (spec.RequiredSource != null && (spec.RequiredSource.Bytes <= 0 || !IsSha256(spec.RequiredSource.Sha256)))))
		{
			throw new InvalidOperationException("Embedded Field Fix asset manifest drifted.");
		}
	}

	private static void ValidatePreimage(AssetSpec spec, byte[] bytes)
	{
		string hash = Hash(bytes);
		bool num = Matches(spec.Desired, bytes.LongLength, hash);
		bool flag = spec.Preimages.Any((AssetIdentity preimage) => Matches(preimage, bytes.LongLength, hash));
		if (!num && !flag)
		{
			throw new InvalidOperationException(spec.Path + " is neither a pinned source preimage nor the desired asset.");
		}
	}

	private static void ValidateDesired(AssetSpec spec, byte[] bytes)
	{
		if (!Matches(spec.Desired, bytes.LongLength, Hash(bytes)))
		{
			throw new InvalidOperationException("Embedded asset identity drifted: " + spec.Path);
		}
	}

	private static void ValidateRequiredSource(AssetSpec spec, MethodInfo getFileEntry, MethodInfo pathMethod, MethodInfo readBytesMethod)
	{
		if (spec.RequiredSourcePath != null && spec.RequiredSource != null)
		{
			object obj = getFileEntry.Invoke(null, new object[1] { spec.RequiredSourcePath }) ?? throw new InvalidOperationException("Required source asset is absent: " + spec.RequiredSourcePath);
			ValidateEntryPath(pathMethod, obj, spec.RequiredSourcePath);
			byte[] array = (byte[])(readBytesMethod.Invoke(obj, null) ?? throw new InvalidOperationException("Source IGamedataEntry.ReadBytes returned null."));
			if (!Matches(spec.RequiredSource, array.LongLength, Hash(array)))
			{
				throw new InvalidOperationException("Required source asset identity drifted: " + spec.RequiredSourcePath);
			}
		}
	}

	private static void ValidateRequiredSource(AssetSpec spec, IDictionary<string, byte[]> cache)
	{
		if (spec.RequiredSourcePath == null || spec.RequiredSource == null || (cache.TryGetValue(spec.RequiredSourcePath, out byte[] value) && Matches(spec.RequiredSource, value.LongLength, Hash(value))))
		{
			return;
		}
		throw new InvalidOperationException("Test cache source identity drifted: " + spec.RequiredSourcePath);
	}

	private static bool Matches(AssetIdentity identity, long bytes, string hash)
	{
		if (bytes == identity.Bytes)
		{
			return string.Equals(hash, identity.Sha256, StringComparison.OrdinalIgnoreCase);
		}
		return false;
	}

	private static void ValidateEntryPath(MethodInfo pathMethod, object entry, string expectedPath)
	{
		string text = (string)(pathMethod.Invoke(entry, null) ?? throw new InvalidOperationException("IGamedataEntry.Path returned null."));
		if (!string.Equals(NormalizePath(text), expectedPath, StringComparison.OrdinalIgnoreCase))
		{
			throw new InvalidOperationException("Gamedata ID collision for " + expectedPath + ": " + text);
		}
	}

	private static void EnsureNotLoaded(object dictionary, uint id, string path)
	{
		if ((bool)((dictionary.GetType().GetMethod("ContainsKey", BindingFlags.Instance | BindingFlags.Public, null, new Type[1] { typeof(uint) }, null) ?? throw new MissingMethodException(dictionary.GetType().FullName, "ContainsKey(uint)")).Invoke(dictionary, new object[1] { id }) ?? throw new InvalidOperationException("ContainsKey returned null.")))
		{
			throw new InvalidOperationException("Asset was loaded before deterministic gamedata ownership: " + path);
		}
	}

	private static List<Exception> RollBack(IEnumerable<GamedataMutation> mutations, MethodInfo addGamedataEntry, MethodInfo getFileEntry, MethodInfo readBytesMethod, MethodInfo tryRemove, object indexedEntries)
	{
		List<Exception> list = new List<Exception>();
		foreach (GamedataMutation item2 in mutations.Reverse())
		{
			if (!item2.Assigned)
			{
				continue;
			}
			try
			{
				if (item2.Original == null)
				{
					if (getFileEntry.Invoke(null, new object[1] { item2.Asset.Spec.Path }) != null)
					{
						object[] parameters = new object[2] { item2.Id, null };
						if (!(bool)(tryRemove.Invoke(indexedEntries, parameters) ?? throw new InvalidOperationException("TryRemove returned null.")))
						{
							throw new InvalidOperationException("Could not remove newly added gamedata entry: " + item2.Asset.Spec.Path);
						}
					}
					if (getFileEntry.Invoke(null, new object[1] { item2.Asset.Spec.Path }) != null)
					{
						throw new InvalidOperationException("Newly added gamedata entry survived rollback: " + item2.Asset.Spec.Path);
					}
				}
				else
				{
					addGamedataEntry.Invoke(null, new object[1] { item2.Original });
					object obj = getFileEntry.Invoke(null, new object[1] { item2.Asset.Spec.Path }) ?? throw new InvalidOperationException("Rolled-back gamedata entry vanished for " + item2.Asset.Spec.Path);
					byte[] first = (byte[])(readBytesMethod.Invoke(obj, null) ?? throw new InvalidOperationException("Rolled-back IGamedataEntry.ReadBytes returned null."));
					if (item2.OriginalBytes == null || !first.SequenceEqual(item2.OriginalBytes))
					{
						throw new InvalidOperationException("Rolled-back gamedata bytes differ from the exact preimage: " + item2.Asset.Spec.Path);
					}
				}
				item2.Assigned = false;
			}
			catch (Exception item)
			{
				list.Add(item);
			}
		}
		return list;
	}

	private static Type FindSingleLoadedType(string fullName)
	{
		Type[] array = (from assembly in AppDomain.CurrentDomain.GetAssemblies()
			select assembly.GetType(fullName, throwOnError: false) into type
			where type != null
			select type).Cast<Type>().ToArray();
		if (array.Length != 1)
		{
			throw new InvalidOperationException($"Expected one loaded {fullName} type, found {array.Length}.");
		}
		return array[0];
	}

	private static string Hash(byte[] bytes)
	{
		using SHA256 sHA = SHA256.Create();
		return BitConverter.ToString(sHA.ComputeHash(bytes)).Replace("-", "");
	}

	private static string Hash(Stream stream)
	{
		using SHA256 sHA = SHA256.Create();
		return BitConverter.ToString(sHA.ComputeHash(stream)).Replace("-", "");
	}

	private static bool IsSha256(string value)
	{
		if (value.Length == 64)
		{
			return value.All(Uri.IsHexDigit);
		}
		return false;
	}

	private static string NormalizePath(string path)
	{
		return path.Replace('\\', '/').TrimStart(new char[1] { '/' });
	}

	private static void Log(string message)
	{
		string text = "[SCOM Field Fixes] " + message;
		try
		{
			Console.WriteLine(text);
		}
		catch
		{
		}
		try
		{
			(from assembly in AppDomain.CurrentDomain.GetAssemblies()
				select assembly.GetType("UnityEngine.Debug", throwOnError: false)).FirstOrDefault((Type type) => type != null)?.GetMethod("Log", new Type[1] { typeof(object) })?.Invoke(null, new object[1] { text });
		}
		catch
		{
		}
	}

